@StochasticAbstraction.exact_unique : ∀ {X : Type u_1} {R : Type u_2} {A : Type u_3} (K : A → X → PMF X) (q : X → R),
  Function.Surjective q →
    ∀ (L M : A → R → PMF R), StochasticAbstraction.Exact K q L → StochasticAbstraction.Exact K q M → L = M

@StochasticAbstraction.exact_iff_all_initial_laws : ∀ {X : Type u_1} {R : Type u_2} {A : Type u_3} (K : A → X → PMF X)
  (q : X → R) (L : A → R → PMF R),
  StochasticAbstraction.Exact K q L ↔ ∀ (a : A) (μ : PMF X), PMF.map q (μ.bind (K a)) = (PMF.map q μ).bind (L a)

@StochasticAbstraction.observationPolicy_factors : ∀ {X : Type u_1} {R : Type u_2} {O : Type u_3} {A : Type u_4}
  (q : X → R) (p : X → O) (d : R → O),
  (∀ (x : X), d (q x) = p x) →
    ∀ (chooseO : StochasticAbstraction.Policy O A) (past : List (X × A)) (x : X),
      StochasticAbstraction.observationPolicy p chooseO past x =
        StochasticAbstraction.observationPolicy d chooseO (StochasticAbstraction.mapHistory q past) (q x)

@StochasticAbstraction.joint_sensor_exact : ∀ {X : Type u_1} {R : Type u_2} {O : Type u_3} {A : Type u_4}
  (J : A → X → PMF (X × O)) (q : X → R) (Jbar : A → R → PMF (R × O)),
  (∀ (a : A) (x : X), PMF.map (StochasticAbstraction.sensorCode q) (J a x) = Jbar a (q x)) →
    StochasticAbstraction.Exact (StochasticAbstraction.sensorStep J) (StochasticAbstraction.sensorCode q)
      (StochasticAbstraction.sensorStep Jbar)

@StochasticExamples.no_trace_based_test_separates : ∀ {D : Type u_1} (n : ℕ) (test : List Bool → PMF D),
  (StochasticExamples.trace n StochasticExamples.State.s).bind test =
    (StochasticExamples.trace n StochasticExamples.State.t).bind test
